# python
from openpyxl.utils import column_index_from_string

# reuse map_data and blue_cells from context

def coord_to_rc(coord):
    # split letters and digits
    for i, c in enumerate(coord):
        if c.isdigit():
            col = column_index_from_string(coord[:i])
            row = int(coord[i:])
            return (row, col)
    return None

cell_map = {}
blue_indices = set()
for coord, info in map_data.items():
    rc = coord_to_rc(coord)
    cell_map[rc] = info
for coord in blue_cells:
    blue_indices.add(coord_to_rc(coord))

print('cell_map sample:', list(cell_map.items())[:10])
print('blue_indices sample:', list(blue_indices)[:10])
