Layered expansion preview up to 5 moves:

```python
# python
from collections import deque
start = (1,1)
DIRECTIONS = {'up':(-2,0),'down':(2,0),'left':(0,-2),'right':(0,2)}

layers = {0:[start]}
seen = {start}
prev_dir_map = {start: None}
for depth in range(1,6):
    layers[depth] = []
    for r,c in layers[depth-1]:
        prev = prev_dir_map[(r,c)]
        for d,(dr,dc) in DIRECTIONS.items():
            if prev and ((prev=='up' and d=='down') or (prev=='down' and d=='up') or (prev=='left' and d=='right') or (prev=='right' and d=='left')):
                continue
            nr,nc = r+dr,c+dc
            if 1<=nr<=20 and 1<=nc<=9 and (nr,nc) not in blue_indices:
                if (nr,nc) not in seen:
                    seen.add((nr,nc))
                    layers[depth].append((nr,nc))
                    prev_dir_map[(nr,nc)] = d
    print('Depth', depth, 'nodes:', layers[depth])
